<?php declare(strict_types=1);namespace Tests\Unit\Arena;use App\Application\Arena\Service\AnswerDuelService;use App\Application\Performance\Port\TransactionManagerInterface;use App\Domain\Arena\Entity\Duel;use App\Domain\Arena\Enum\DuelStatus;use App\Domain\Arena\Repository\DuelAnswerVerifierInterface;use App\Domain\Arena\Repository\DuelRepositoryInterface;use PHPUnit\Framework\TestCase;final class AnswerDuelServiceTest extends TestCase{private function duel(\DateTimeImmutable $deadline):Duel{return new Duel('d','CODE','u',2,1,5,30,new \DateTimeImmutable('-1 minute'),DuelStatus::QUESTION_OPEN,1,new \DateTimeImmutable('-10 seconds'),$deadline);}private function service(DuelRepositoryInterface $repo,DuelAnswerVerifierInterface $verifier):AnswerDuelService{$tx=new class implements TransactionManagerInterface{public function transactional(callable $callback):mixed{return$callback();}};return new AnswerDuelService($repo,$verifier,$tx);}public function testPersistsOnlyFirstAnswer():void{$repo=$this->createMock(DuelRepositoryInterface::class);$repo->method('findForParticipant')->willReturn($this->duel(new \DateTimeImmutable('+10 seconds')));$repo->expects(self::once())->method('appendAnswer')->willReturn(false);$verifier=$this->createMock(DuelAnswerVerifierInterface::class);$verifier->method('verify')->willReturn(true);self::assertFalse($this->service($repo,$verifier)->answer('d','u','o'));}public function testRejectsExpiredQuestion():void{$repo=$this->createMock(DuelRepositoryInterface::class);$repo->method('findForParticipant')->willReturn($this->duel(new \DateTimeImmutable('-1 second')));$this->expectException(\DomainException::class);$this->service($repo,$this->createMock(DuelAnswerVerifierInterface::class))->answer('d','u','o');}public function testRejectsOptionOutsideFrozenQuestion():void{$repo=$this->createMock(DuelRepositoryInterface::class);$repo->method('findForParticipant')->willReturn($this->duel(new \DateTimeImmutable('+10 seconds')));$verifier=$this->createMock(DuelAnswerVerifierInterface::class);$verifier->method('verify')->willReturn(null);$this->expectException(\DomainException::class);$this->service($repo,$verifier)->answer('d','u','o');}}
